 CREATE PROCEDURE Sp_PartyWiseJobOrderBal (@Coycode as int, @OrdId as nvarchar(1000),@PId as nvarchar(1000),@OrderType varchar(15),@StyleNo as NVarchar(4000), @Id As Int)  AS  BEGIN  DECLARE @SQLSTR AS NVARCHAR(4000) Set @SQLSTR =N'select x.coyid, MAs_exporter.exportername, OrderMAs.jobno as OrdNo,ORdermas.finyear as ORdFinyear,OrderMAs.buyordNo,X.styleno,unit.exportername as unitname,Fabdesc ,ColorDesc ,CountName ,x.gsm,gg,ll,KDia.Dia as KnitDia,fdia.Dia as FinDia,PrgKDia.Dia as PrgKnitdia,fingsm,sum(Jobkgs-RetKgs) JobOrderKgs,   sum(Jobmtr-RetMtr) JobOrderMtr ,sum(consKgs) ConsKgs,sum(ConsMtr) ConsMtr,sum(JobKgs-RetKgs-conskgs ) as BalKgs ,sum(JobMtr-RetMtr-ConsMtr ) as BalMtr, x.FabId,x.CntId, X.colId, X.DiaId, X.FinDiaId,X.PrgKnitDiaId  from 	( select  ordid,styleno,coyid,fabid ,colid,cntid,gsm,gg,ll,Diaid,findiaid,fingsm,0 as Jobkgs,0 as JobMtr,0 as RetKgs,0 as RetMtr ,sum(Reqkgs) as Conskgs,sum(ReqMtr) as ConsMtr,Diaid as PrgKnitDiaId from Pro_ReqJob_1_PcsGrn Where PcsGrnId = @Id group by ordid,styleno,coyid, fabid ,colid,cntid,gsm,gg,ll,Diaid,findiaid,fingsm union select trs_del2.Ordid,trs_del2.styleno ,trs_del1.coycode, fabid,colid,cntid,gsm,gg,ll,diaid,findiaid,fingsm ,sum(trs_del2.Kg) as JobKgs,    sum(trs_del2.mtr) as JobMtr,0 as RetKgs,0 as RetMtr,0 as ConsMtr,0 as Conskgs,PrgKnitDiaId from  TRs_del1 inner join trs_del2 on trs_del1.id =trs_del2.id inner join stocktable on trs_del2.stockid=stocktable.stockid where trs_del1.trtype=21 and DEltype=''P'' group by trs_del1.coycode,trs_del2.ordid,trs_del2.styleno,   fabid,colid,cntid,gsm,gg,ll,Diaid,findiaid,fingsm,PrgKnitDiaId union select trs_grn2.Ordid,trs_grn2.styleno ,trs_grn1.coycode, fabid,colid,cntid,gsm,gg,ll,diaid,findiaid,fingsm ,0 as JobKgs,0 as JobMtr,sum(trs_grn2.RecKgs) as RetKgs ,sum(trs_grn2.Recmtr) as RetMtr ,0 as Conskgs,0 as ConsMtr,PrgKnitDiaId from  trs_grn1 inner join trs_grn2 on trs_grn1.id =trs_grn2.id inner join stocktable on trs_grn2.stockid=stocktable.stockid where trs_grn1.Grntype=''FabricRetToUnit'' group by trs_grn1.coycode,trs_grn2.ordid,trs_grn2.styleno,   fabid,colid,cntid,gsm,gg,ll,Diaid,findiaid,fingsm,PrgKnitDiaId  )x INNER JOIN  OrderMas (nolock) on x.ordid=ordermas.ordid  LEFT OUTER JOIN Mas_fabric(nolock) on x.fabid=MAs_fabric.fabid LEFT OUTER JOIN  Mas_color (nolock) on  x.colid=MAs_color.ColID LEFT OUTER JOIN  Mas_count (nolock) on x.CntID =MAs_count.CountID  left outer join MAs_exporter unit (nolock) on x.coyid = unit.Expid LEFT OUTER JOIN  Mas_dia KDia (nolock)  on  x.Diaid=KDia.Diaid left outer join MAs_Dia FDia (nolock) on  x.Diaid=FDia.Diaid  LEFT OUTER JOIN  Mas_Dia PrgKDia (nolock)  on x.PrgKnitDiaId=PrgKDia.Diaid   LEFT OUTER JOIN  Mas_Exporter on ordermas.expid= MAs_exporter.expid where x.coyid = @coycode  and Ordertype in (select IDStr from fnSplitter_Str(@OrderType)) ' If Len(Rtrim(@StyleNo))>0 Begin Set @SQLSTR=@SQLSTR+N' AND x.StyleNo in (Select IDStr From fnSplitter_Str(@StyleNo))' End if len(RTRIM(@OrdId))>0  begin  Set @SQLSTR=@SQLSTR+N' AND x.OrdId in (Select ID From fnSplitter(@OrdId))' end Set @SQLSTR=@SQLSTR+N' group by x.coyid, MAs_exporter.exportername, ordermas.expid, OrderMAs.jobno, ORdermas.finyear,OrderMAs.buyordNo, X.styleno, unit.exportername, Fabdesc, ColorDesc, CountName, x.gsm, gg, ll, KDia.Dia, fdia.Dia, fingsm, PrgKDia.Dia, x.FabId,x.CntId, X.colId , X.DiaId, X.FinDiaId,X.PrgKnitDiaId  '   Exec SP_EXECUTESQL @SQLSTR,N'@Coycode int,@OrdId nvarchar(200),@Pid nvarchar(200),@OrderType varchar(15), @StyleNo as NVarchar(4000),@Id As Int', @Coycode=@coycode,@OrdId=@OrdId,@Pid=@Pid,@OrderType=@OrderType, @StyleNo=@StyleNo,@Id=@Id end